function toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function splash(t,ms=5000){$('#sp')?.remove();const s=document.createElement('div');s.id='sp';s.onclick=()=>s.remove();s.innerHTML=`<div><img class=lg3 src="${logoSrc()}" alt=""><p>${E(t)}</p></div>`;document.body.append(s);setTimeout(()=>s.remove(),ms)}
function beep(){try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=880;g.gain.value=.15;o.start();o.stop(a.currentTime+.3)}catch(e){}}
function ping(m){beep();toast(m);try{if(Notification.permission==='granted')new Notification(db.cfg.n,{body:m})}catch(e){}}
function detect(o){const ids=new Set(o.pedidos.map(x=>x.id));
if(ses?.r==='a'){const n=db.pedidos.filter(x=>!ids.has(x.id)&&x.est==='nuevo');if(n.length)ping('🔔 Pedido nuevo #'+n[0].id+(n.length>1?' y '+(n.length-1)+' más':''))}
if(ses?.r==='m')db.pedidos.forEach(x=>{const y=o.pedidos.find(z=>z.id===x.id);if((x.m===ses.u||x.o==='web')&&x.est==='listo'&&y&&y.est!=='listo')ping('✅ Pedido #'+x.id+' listo para '+x.d+(x.o==='web'?' · COMPRA WEB, cobrar':''))})}
const abre=()=>{const d=new Date(),h=db.cfg.h[d.getDay()],x=d.getHours()+d.getMinutes()/60;return !!h&&x>=h[0]&&x<h[1]};
function tick(){const e=$('#clk');if(!e)return;const n=new Date();e.textContent=n.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit',second:'2-digit'});$('#cdt').textContent=n.toLocaleDateString('es-CO',{weekday:'long',day:'numeric',month:'short'})+(abre()?' · 🟢 Abierto':' · 🔴 Cerrado')}
setInterval(tick,1000);
const DN=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'],h12=n=>{const h=Math.floor(n);return (h%12||12)+':'+String(Math.round((n-h)*60)).padStart(2,'0')+(h<12?' am':' pm')};
const foot=()=>`<div class=ft><div class=r style="align-items:flex-start;flex-wrap:wrap"><div><b>📍 Güepsa, Santander</b><br>${E(db.cfg.n)} · ${E(db.cfg.w2)}</div><div><a class="btn y s" href="tel:${E(db.cfg.tel)}">📞 ${E(db.cfg.tel)}</a> <a class="btn s wa" target=_blank rel=noopener href="https://wa.me/57${E(db.cfg.tel)}">${WA} ${E(db.cfg.tel)}</a></div></div><div class=cp>© ${new Date().getFullYear()} ${E(db.cfg.n)} · Software desarrollado por <b>ING. JOSÉ LUIS ARIZA</b> · Todos los derechos reservados</div></div><a class=hid href="#personal" aria-label="Acceso del personal" onclick="location.hash='personal';render();return false">🔒</a>`;
const shell=(h,staff)=>`<div class=wrap><div class=top><a class=logo2 href="#" aria-label="Ir al inicio"><img class=lgw src="${logoSrc()}" alt="${E(db.cfg.n)}"></a><div class=dock><span class=bd>📍 Güepsa, Santander</span><div class=clock><b id=clk></b><small id=cdt></small></div>${staff?`<span class=bd>${E(ses.n)}</span><button class="btn y s" onclick="out()">Salir</button>`:''}${!staff&&ses?`<a class="btn s y" href="#${{a:'cocina',m:'mesera',x:'dev'}[ses.r]}">↩ Mi panel</a>`:''}<div class=pw><button class="btn s y" onclick="T.o=!T.o;render()">🎨 Colores</button>${T.o?`<div class=pal>${Object.entries(PAL).map(([k,[a,b]])=>`<button class="sw${T.p===k?' on':''}" aria-label="Paleta ${k}" title="${({vinotinto:'Vinotinto / blanco',blanconegro:'Blanco / negro'})[k]||k}" style="background:linear-gradient(135deg,${a} 50%,${b} 50%)" onclick="T.p='${k}';T.o=0;setT();render()"></button>`).join('')}</div>`:''}</div><button class="btn s y" aria-label="Modo claro u oscuro" onclick="T.m=T.m==='l'?'d':'l';setT();render()">${T.m==='l'?'🌙':'☀️'}</button></div></div>${h}${foot()}</div>`;

const menu=()=>{const cs=['Todo',...new Set(db.platos.map(p=>p.c))];return `<div class=row style="margin-bottom:1rem">${cs.map(c=>`<button class="chip ct${c===cat?' on':''}" onclick="cat='${E(c)}';render()">${E(c)}</button>`).join('')}</div><div class=grid>${db.platos.filter(p=>cat==='Todo'||p.c===cat).map(p=>`<div class=card>${p.img?`<img class=pim src="${p.img}" alt="${E(p.n)}">`:`<div class=em>${p.e}</div>`}<h3>${E(p.n)}</h3><div class=pills>${p.v.map(v=>`<span class=pl>${E(v.t)}</span>`).join('')}</div>${p.c!=='Bebidas'?`<p class=lv>Lleva</p><div class=pills>${Object.keys(p.i).map(k=>`<span class="pl ig2">${E(k)}</span>`).join('')}</div>`:''}${p.sa?.length&&p.c!=='Bebidas'?`<p class=lv>Salsas</p><div class=pills>${p.sa.map(k=>`<span class=pl>${E(k)}</span>`).join('')}</div>`:''}<p class=pr>desde ${$$(Math.min(...p.v.map(v=>v.p)))}</p><button class="btn s" onclick="pick(${p.id})">Elegir y personalizar</button></div>`).join('')||'<div class=card>No hay platos en esta categoría.</div>'}</div>`};
function pick(id){const p=db.platos.find(x=>x.id===id),b=p.c==='Bebidas',sa=Object.keys(db.ins).filter(k=>db.ins[k].k==='s'),m=document.createElement('div');m.className='md';
m.innerHTML=`<div class=card style="max-width:440px;width:92%;max-height:92vh;overflow:auto">${p.img?`<img class=pim style="height:200px" src="${p.img}" alt="${E(p.n)}">`:''}<h2>${p.e} ${E(p.n)}</h2><label>Tamaño / tipo</label><div class=row>${p.v.map((v,i)=>`<button class="chip vr${i?'':' on'}" onclick="document.querySelectorAll('.vr').forEach(x=>x.classList.remove('on'));this.classList.add('on')">${E(v.t)} · ${$$(v.p)}</button>`).join('')}</div>${p.ex?.length?`<label>Extras <small>(con costo adicional)</small></label><div class=row>${p.ex.map(id=>db.extras.find(x=>x.id===id)).filter(Boolean).map(x=>`<button class="chip px" data-id=${x.id} data-g="${E(x.grp||'')}" onclick="xtog(this)">${E(x.n)} · +${$$(x.p)}</button>`).join('')}</div>`:''}${b?'':`<label>Toca lo que quieras quitar (no cuesta nada)</label><div class=row>${Object.keys(p.i).map(k=>`<button class="chip ig" onclick="this.classList.toggle('off')">${E(k)}</button>`).join('')}</div>`}${sa.length&&!b?`<label>Salsas <small>(las de este plato ya vienen encendidas)</small></label><div class=row>${[...sa].sort((x,y)=>(p.sa||[]).includes(y)-(p.sa||[]).includes(x)).map(k=>`<button class="chip sa${(p.sa||[]).includes(k)?' on':''}" onclick="this.classList.toggle('on')">${E(k)}</button>`).join('')}</div>`:''}<input id=nt placeholder="Nota (ej: bien asada)" style="margin-top:.8rem"><div class=row style="margin-top:.8rem"><button class=btn onclick="addM(${id},0)">Agregar</button>${b?'':`<button class="btn y" onclick="addM(${id},1)">Pedir con todo</button>`}<button class="btn s" onclick="this.closest('.md').remove()">Cerrar</button></div></div>`;document.body.append(m)}
function addM(id,all){const p=db.platos.find(x=>x.id===id),m=$('.md'),vi=[...m.querySelectorAll('.vr')].findIndex(x=>x.classList.contains('on')),v=p.v[vi];
const XS=[...m.querySelectorAll('.px.on')].map(z=>db.extras.find(e=>e.id==z.dataset.id)).filter(Boolean).map(e=>({n:e.n,ins:e.ins,q:e.q,u:e.u,p:e.p}));cart.push({id,e:p.e,n:p.n,v:v.t,p:v.p+XS.reduce((a,e)=>a+e.p,0),xs:XS,q:all?[]:[...m.querySelectorAll('.ig.off')].map(c=>c.textContent),sa:all?(p.sa||[]).filter(k=>db.ins[k]):[...m.querySelectorAll('.sa.on')].map(c=>c.textContent),nota:m.querySelector('#nt').value});m.remove();render()}
const chd=v=>{fm={d:v,nom:'',dir:'',tel:'',mp:fm.mp};render()};
function ticket(){const mes=ses?.r==='m',ops=mes?[...Array(db.cfg.mesas)].map((_,i)=>'Mesa '+(i+1)).concat('Domicilio'):['Domicilio','Recoger en local','En el local'],d=fm.d=ops.includes(fm.d)?fm.d:(mes?'':ops[0]),pm=Object.values(db.cfg.pay).filter(x=>x.on);if(!pm.some(x=>x.n===fm.mp))fm.mp=pm[0]?.n||'';const cu=pm.find(x=>x.n===fm.mp);
return `<aside class=tk><h3>${edit?'Editando #'+edit:'PRE-TICKET'}</h3><hr>${cart.length?cart.map((c,i)=>`<p class=r><span>${c.e} ${E(c.n)} <small>(${E(c.v)})</small>${c.q.length?`<br><small>sin ${E(c.q.join(', '))}</small>`:''}${xt(c)}${c.sa.length?`<br><small>salsas: ${E(c.sa.join(', '))}</small>`:''}${c.nota?`<br><small>“${E(c.nota)}”</small>`:''}</span><span>${$$(c.p)} <button class=x aria-label="Quitar" onclick="cart.splice(${i},1);render()">✕</button></span></p>`).join(''):'<p class=sm>Elige un plato del menú para empezar tu pedido.</p>'}<hr><p class=r><b>Total</b><b>${$$(tot())}</b></p>
<label>Destino<select onchange="chd(this.value)">${mes?`<option value="" ${d?'':'selected'} disabled>Elige la mesa o domicilio…</option>`:''}${ops.map(o=>`<option ${o===d?'selected':''}>${o}</option>`).join('')}</select></label>
${!mes&&d==='En el local'?`<label>Tu mesa<select onchange="fm.mesa=this.value"><option value="">Elige tu mesa…</option>${[...Array(db.cfg.mesas)].map((_,i)=>`<option value=${i+1} ${fm.mesa==i+1?'selected':''}>Mesa ${i+1}</option>`).join('')}</select></label>`:''}${!mes||d==='Domicilio'?`<label>Nombre<input value="${E(fm.nom)}" oninput="fm.nom=this.value"></label>`:''}${d==='Domicilio'?`<label>Dirección<input value="${E(fm.dir)}" oninput="fm.dir=this.value"></label>`:''}${d==='Domicilio'||d==='Recoger en local'?`<label>Teléfono (opcional)<input type=tel inputmode=tel value="${E(fm.tel)}" oninput="fm.tel=this.value" placeholder="Para avisarte cuando esté listo"></label>`:''}
${mes?'':`<label>¿Cómo pagarás?<select onchange="fm.mp=this.value;render()">${pm.map(x=>`<option ${x.n===fm.mp?'selected':''}>${E(x.n)}</option>`).join('')}</select></label>${cu?.num?`<p class=sm>Transfiere a ${E(cu.n)}: <b>${E(cu.num)}</b></p>`:''}<p class=sm>La mesera cobra al entregarte el pedido.</p>`}
<button class=btn style="width:100%;margin-top:.8rem" onclick="send()">${edit?'Guardar cambios':'Enviar pedido'}</button>${edit?'<button class="btn y s" style="margin-top:.5rem" onclick="edit=0;cart=[];render()">Cancelar edición</button>':''}</aside>`}
function send(){const mes=ses?.r==='m',d=fm.d;if(!cart.length)return toast('Primero agrega un plato a tu pedido');if(mes&&!d)return toast('Elige la mesa o domicilio');if(!mes&&d==='En el local'&&!fm.mesa)return toast('Elige tu mesa');
if((!mes||d==='Domicilio')&&!fm.nom.trim())return toast('Escribe el nombre');if(d==='Domicilio'&&!fm.dir.trim())return toast('Escribe la dirección');
conf()}
function conf(){const mes=ses?.r==='m',m=document.createElement('div');m.className='md';
m.innerHTML=`<div class=card style="max-width:430px;width:92%;max-height:92vh;overflow:auto"><h2>¿Confirmas el pedido?</h2><p class=sm style="margin:.4rem 0">Revisa que todo esté bien antes de enviarlo a cocina.</p><hr>${cart.map(c=>`<p class=r><span>${c.e} <b>${E(c.n)}</b> (${E(c.v)})${c.q.length?`<br><small>sin ${E(c.q.join(', '))}</small>`:''}${xt(c)}${c.sa.length?`<br><small>salsas: ${E(c.sa.join(', '))}</small>`:''}${c.nota?`<br><small>“${E(c.nota)}”</small>`:''}</span><b>${$$(c.p)}</b></p>`).join('')}<hr><p class=r style="font-size:1.3rem"><b>Total</b><b>${$$(tot())}</b></p><p class=sm style="margin:.5rem 0">${E(fm.d)}${!mes&&fm.d==='En el local'?' · Mesa '+E(fm.mesa):''}${fm.nom?' · '+E(fm.nom):''}${fm.dir?' · '+E(fm.dir):''}${fm.tel?' · 📞 '+E(fm.tel):''}${mes?'':' · Pago: '+E(fm.mp)}</p><div class=row><button class=btn onclick="doSend()">✅ Confirmar y enviar</button><button class="btn y" onclick="this.closest('.md').remove()">Volver a revisar</button></div></div>`;document.body.append(m)}
function doSend(){$('.md')?.remove();const mes=ses?.r==='m',d=!mes&&fm.d==='En el local'?'En el local · Mesa '+fm.mesa:fm.d;const id=edit||++db.seq,o={id,t:Date.now(),o:mes?'mesera':'web',m:mes?ses.u:null,d,nom:fm.nom,dir:d==='Domicilio'?fm.dir:'',tel:d==='Domicilio'||d==='Recoger en local'?(fm.tel||'').trim():'',it:cart,tot:tot(),est:'nuevo',pg:'pendiente',mp:mes?'':fm.mp};
if(!mes){o.tk=Math.random().toString(36).slice(2)+Date.now().toString(36);SS.last=id;SS.tk=o.tk}db.pedidos=db.pedidos.filter(x=>x.id!==id).concat(o).sort((a,b)=>a.id-b.id);lg((edit?'Editó':'Envió')+' pedido #'+id+' · '+d+' · '+$$(o.tot));save();cart=[];edit=0;fm={d:'',nom:'',dir:'',tel:'',mp:fm.mp};render();recibo(id)}
function recibo(id){const o=db.pedidos.find(x=>x.id===id);if(!o)return;if(!((ses&&['m','a'].includes(ses.r))||(o.tk&&SS.last==o.id&&SS.tk===o.tk)))return toast('Solo puedes ver tu propia tirilla');$('.md')?.remove();const m=document.createElement('div'),pm=Object.values(db.cfg.pay).find(x=>x.n===o.mp),si=Math.max(0,['nuevo','preparando','listo','entregado'].indexOf(o.est));m.className='md';
m.innerHTML=`<div class=rc><div class=rh><img class=lg2 style="height:72px" src="${logoSrc()}" alt=""><h3>${E(db.cfg.n)}</h3><small>Güepsa, Santander · ${E(db.cfg.tel)}</small></div><p class=r><b>PEDIDO #${o.id}</b><small>${fd(o.t)}</small></p><p>${E(o.d)}${o.nom?' · '+E(o.nom):''}${o.tel?'<br>📞 '+E(o.tel):''}</p><hr>${o.it.map(c=>`<p class=r><span>${c.e} ${E(c.n)} <small>(${E(c.v)})</small>${c.q.length?`<br><small>sin ${E(c.q.join(', '))}</small>`:''}${xt(c)}${c.sa.length?`<br><small>+ ${E(c.sa.join(', '))}</small>`:''}</span><span>${$$(c.p)}</span></p>`).join('')}<hr><p class=r style="font-size:1.4rem"><b>TOTAL</b><b>${$$(o.tot)}</b></p><p class=sm>${o.pg==='pagado'?'✅ Pagado con '+E(o.mp):'⏳ Pago pendiente'+(o.mp?' · '+E(o.mp):'')}</p>${pm?.num&&o.pg!=='pagado'?`<p class=sm>Transfiere a ${E(pm.n)}: <b>${E(pm.num)}</b></p>`:''}<div class=stp>${['Recibido','Preparando','Listo','Entregado'].map((s,i)=>`<b class="${i<=si?'on':''}">${i<=si?'●':'○'} ${s}</b>`).join('')}</div><hr><p style="text-align:center"><b>${E(db.cfg.w4)} 💛</b><br><small>${E(db.cfg.w2)}</small></p><div class="row no" style="margin-top:.8rem"><button class="btn s" onclick="print()">🖨️ Imprimir</button>${ses&&['m','a'].includes(ses.r)?`<a class="btn s wa" target=_blank rel=noopener href="${waLink(o)}" onclick="lg('Envió ticket #${o.id} al WhatsApp');save()">${WA} Enviar al WhatsApp</a>`:''}<button class="btn s y" onclick="this.closest('.md').remove()">Cerrar</button></div></div>`;document.body.append(m)}

function cliente(){if(!activo())return app(shell(`<div class=card style="max-width:480px;margin:3rem auto;text-align:center"><div class=em style="margin:0 auto .6rem">⏸️</div><h2>Servicio en pausa</h2><p class=sm style="margin-top:.6rem">Estamos renovando el servicio. Escríbenos por WhatsApp al ${E(db.cfg.tel)}.</p></div>`));
const c=db.cfg,o=db.pedidos.find(x=>x.id==SS.last&&x.tk&&x.tk===SS.tk&&!['entregado','cancelado'].includes(x.est));
app(shell(`<section class=hero><span class=stk style="--r:-12deg;right:2%;top:0">🍔</span><span class=stk style="--r:10deg;right:20%;top:90px;animation-delay:-1s">🌭</span><span class=stk style="--r:-6deg;right:6%;top:170px;animation-delay:-2s">🍕</span><span class=stk style="--r:14deg;right:30%;top:18px;animation-delay:-3s">🥤</span><span class=stk style="--r:-16deg;right:36%;top:140px;animation-delay:-1.5s">🌮</span><div class=hl><img class=hlogo src="${logoSrc()}" alt="${E(c.n)}"><h1>${E(c.w1)}</h1></div><p>${E(c.w2)}</p><span class=st>${E(c.w3)}</span><span class="st y">${E(c.w4)}</span></section><div class=mq><span>🍔 Hamburguesas ✦ 🍕 Pizzas ✦ 🌭 Perros ✦ 🌮 Tacos ✦ 🫓 Arepas ✦ 🍟 Salchipapas ✦ 🥤 Bebidas frías ✦ ${E(c.w4)} ✦ </span></div>${cartel()}${o?`<div class=card style="background:var(--a2);color:#1c120a;margin-bottom:1rem" class=r><b>📦 Tu pedido #${o.id}: ${o.est==='listo'?'¡listo!':o.est}</b> <button class="btn s" onclick="recibo(${o.id})">Ver mi tirilla</button> <button class="btn s y" onclick="delete SS.last;delete SS.tk;render()">Ocultar</button></div>`:''}<div class=cols><div>${menu()}</div>${ticket()}</div>`));tick()}

function login(){app(shell(`<div class=card style="max-width:380px;margin:3rem auto"><h2>Acceso del personal</h2><p class=sm style="margin:.5rem 0 1rem">Meseras, cocina y desarrollador entran por aquí.</p><label>Usuario<input id=lu autocomplete=username></label><label>Contraseña<input id=lp type=password autocomplete=current-password onkeydown="event.key==='Enter'&&entrar()"></label><button class=btn style="width:100%;margin-top:1rem" onclick="entrar()">Entrar</button></div>`));tick()}
function entrar(){const u=$('#lu').value.trim().toLowerCase(),p=$('#lp').value;let s=null;
if(u===db.dev.u&&p===db.dev.p)s={r:'x',u,n:'Desarrollador'};else if(u===db.adm.u&&p===db.adm.p)s={r:'a',u,n:'Cocina'};else{const m=db.meseras.find(x=>x.u===u&&x.p===p);if(m)s={r:'m',u,n:m.n}}
if(!s)return toast('Usuario o contraseña incorrectos');if(!activo()&&s.r!=='x')return toast('El servicio está suspendido. Contacta al desarrollador.');
ses=s;SS.s=JSON.stringify(s);lg('Ingresó al sistema');save();try{Notification.requestPermission()}catch(e){}splash(db.cfg.w4,2500);cart=[];location.hash={a:'cocina',m:'mesera',x:'dev'}[s.r];render()}
function out(){lg('Cerró sesión');save();ses=null;delete SS.s;location.hash='';render()}

function dev(){const a=activo(),ph={n:'Nombre',u:'Usuario',p:'Contraseña'},ci=(k,i,f,v)=>`<input value="${E(v)}" placeholder="${ph[f]}" aria-label="${ph[f]}" onchange="cred('${k}',${i},'${f}',this.value)">`;
app(shell(`<h2>Opciones de desarrollador</h2><div class=card style="margin:1rem 0"><h3>Suscripción anual</h3><p style="margin:.7rem 0">Estado: <span class=bd>${a?'🟢 ACTIVA':'🔴 INACTIVA'}</span><br><small>Vence: ${new Date(db.sub.hasta).toLocaleDateString('es-CO',{dateStyle:'long'})}</small></p><div class=row><button class=btn onclick="subs(1)">Activar / renovar 1 año</button><button class="btn y" onclick="subs(0)">Desactivar</button></div></div>
<div class=card style="margin-bottom:1rem"><h3>Acceso de desarrollador</h3><p class=sm>Usuario y contraseña con los que entras a esta pantalla.</p><div class=fg>${ci('d',0,'u',db.dev.u)}${ci('d',0,'p',db.dev.p)}</div></div>
<div class=card style="margin-bottom:1rem"><h3>Administración de cocina</h3><div class=fg>${ci('a',0,'u',db.adm.u)}${ci('a',0,'p',db.adm.p)}</div><button class="btn s y" style="margin-top:.6rem" onclick="if(confirm('¿Restablecer cocina a admin / admin123?')){db.adm={u:'admin',p:'admin123'};lg('Restableció el acceso de cocina');save();render()}">Restablecer a admin / admin123</button></div>
<div class=card><h3>Meseras</h3><p class=sm>Cambia nombre, usuario o contraseña si alguien los olvida.</p>${db.meseras.map((m,i)=>`<div class=fg>${ci('m',i,'n',m.n)}${ci('m',i,'u',m.u)}${ci('m',i,'p',m.p)}<button class="btn s" onclick="if(confirm('¿Quitar a ${E(m.n)}?'))delMes(${i})">Quitar</button></div>`).join('')}<div class=fg style="border-top:2px dashed var(--ln);padding-top:.6rem"><input id=mn placeholder=Nombre><input id=mu placeholder=Usuario><input id=mp placeholder=Contraseña><button class=btn onclick="addMes()">Agregar mesera</button></div></div>`,1))}
function cred(k,i,f,v){v=v.trim();if(!v){render();return toast('No puede quedar vacío')}if(f==='u'){v=v.toLowerCase();const cur=k==='d'?db.dev.u:k==='a'?db.adm.u:db.meseras[i].u;if(v!==cur&&[db.dev.u,db.adm.u,...db.meseras.map(m=>m.u)].includes(v)){render();return toast('Ese usuario ya existe')}}
const o=k==='d'?db.dev:k==='a'?db.adm:db.meseras[i];o[f]=v;lg('Cambió '+({d:'el acceso de desarrollador',a:'el acceso de cocina',m:'datos de la mesera '+(db.meseras[i]||{}).n}[k]));save();toast('Guardado')}
const delMes=i=>{db.meseras.splice(i,1);save();render()};
function subs(a){if(a){db.sub={on:1,hasta:Math.max(Date.now(),db.sub.hasta)+365*864e5}}else db.sub.on=0;lg(a?'Activó la suscripción anual':'Desactivó la suscripción');save();render()}

/* ---------- COCINA ---------- */
function cocina(){const act=db.pedidos.filter(o=>['nuevo','preparando'].includes(o.est));
const tabs=[['p','Pedidos'+(act.length?' ('+act.length+')':'')],['i','Inventario'],['s','Surtidores'],['c','Comidas'],['r','Reporte'],['u','Personal'],['a','Ajustes']];
app(shell(`<div class=tabs>${tabs.map(([k,l])=>`<button class="btn s ${tab===k?'y':''}" onclick="tab='${k}';render()">${l}</button>`).join('')}</div>`+({p:()=>kp(act),i:ki,s:ks,c:kc,r:kr,u:ku,a:ka}[tab])()+'<button class=fab aria-label="Soporte técnico" title="Soporte técnico" onclick="soporte()">🛠️</button>',1));tick()}
const pgb=o=>o.pg==='pagado'?`<span class=bd>✅ Pagado · ${E(o.mp)}</span>`:'<span class=bd>⏳ Cobro pendiente</span>';
const kp=a=>`<h2>En cocina</h2><p class=sm style="margin:.5rem 0 1.2rem">${db.pedidos.filter(o=>o.est==='listo').length} pedido(s) listo(s) esperando entrega.</p>${a.length?`<div class=tks>${a.map(o=>`<div class=tk><div class=r><h3>#${o.id}</h3><span class=bd>${o.o==='web'?'🌐 Web':'🧑‍🍳 '+E(o.m)}</span></div><p><b>${E(o.d)}</b>${o.nom?' · '+E(o.nom):''}${o.dir?'<br>'+E(o.dir):''}${o.tel?'<br>📞 '+E(o.tel):''}</p><hr>${o.it.map(c=>`<p>1× ${c.e} ${E(c.n)} (${E(c.v)})${c.q.length?`<br><small>SIN ${E(c.q.join(', '))}</small>`:''}${xt(c)}${c.sa.length?`<br><small>SALSAS: ${E(c.sa.join(', '))}</small>`:''}${c.nota?`<br><small>“${E(c.nota)}”</small>`:''}</p>`).join('')}<hr><p class=r><small>${hora(o.t)}</small><b>${$$(o.tot)}</b></p><p>${pgb(o)}</p><button class=btn style="width:100%;margin-top:.5rem" onclick="avanza(${o.id})">${o.est==='nuevo'?'Preparar':'Finalizar y avisar'}</button><button class="btn s wa" style="width:100%;margin-top:.5rem" onclick="wa(${o.id})">${WA} Enviar al WhatsApp</button></div>`).join('')}</div>`:'<div class=card>Sin pedidos por ahora. Cuando llegue uno, suena la campana.</div>'}`;
const F={g:1,kg:1000,lb:453.592,und:1},cv=(q,a,b)=>a===b||a==='und'||b==='und'?q:q*F[a]/F[b];
function descontar(o){o.it.forEach(c=>{const p=db.platos.find(x=>x.id==c.id);if(!p)return;const m=p.v.find(v=>v.t===c.v)?.m??1,dec=(k,q,u)=>{const x=db.ins[k];if(x)x.s=Math.max(0,+(x.s-cv(q,u,x.u)).toFixed(3))};for(const k in p.i)if(!c.q.includes(k))dec(k,p.i[k].q*m,p.i[k].u);c.sa.forEach(z=>dec(z,15,'g'));(c.xs||[]).forEach(e=>dec(e.ins,e.q,e.u))})}
function avanza(id){const o=db.pedidos.find(x=>x.id===id);if(o.est==='nuevo'){descontar(o);o.est='preparando';lg('Preparando #'+id)}else{o.est='listo';lg('Finalizó #'+id)}save();render()}
const fmt=x=>`${+(+x.s).toFixed(2)} ${x.u}`,sn=id=>!id||id==='tienda'?'Compra en tienda':(db.sur.find(z=>z.id==id)?.n||'Surtidor eliminado');
const hc=()=>db.compras.slice().reverse().filter(c=>(c.n+' '+fd(c.t)+' '+(c.by||'')+' '+sn(c.sur)).toLowerCase().includes(qc.toLowerCase())).map(c=>`<tr><td>${fd(c.t)}<td>${E(c.n)}<td>${c.q} ${c.u}<td>${$$(c.v)}<td>${E(sn(c.sur))}<td>${E(c.by||'')}</tr>`).join('')||'<tr><td colspan=6>Sin compras registradas</tr>';
const it=t=>Object.entries(db.ins).filter(([,x])=>x.k===t).map(([n,x])=>{const k=encodeURIComponent(n),r=x.c?x.s/x.c:0;return `<tr><td><b>${E(n)}</b> ${x.ed?`<span class=bd title="Cantidad editada ${x.ed} vez/veces">✏️${x.ed}</span>`:''}<td>${x.f?fd(x.f):'—'}<td><input type=number step=any min=0 value="${+(+x.s).toFixed(2)}" style="width:6.5rem" aria-label="Cantidad de ${E(n)}" onchange="setQ('${k}',this.value)"> ${x.u}${r<.2?' ⚠️':''}<td>${E(sn(x.sur))}<td>${x.cost?$$(x.cost):'—'}<td>${E(x.by||'—')}<td style="min-width:80px"><div class=bar><i style="width:${Math.min(100,r*100)}%"></i></div><td><button class="btn s" aria-label="Eliminar" onclick="delIns('${k}')">✕</button></tr>`}).join('')||'<tr><td colspan=8>Sin productos</tr>',
TH='<tr><th>Producto<th>Ingresó<th>Cantidad<th>Surtidor<th>Costo<th>Registró<th>Nivel<th></tr>';
const ki=()=>`<h2>Inventario</h2><p class=sm style="margin:.5rem 0 1rem">La cantidad baja sola con cada plato que preparas, en la misma unidad del inventario. Invertido en total: <b>${$$(db.compras.reduce((a,c)=>a+c.v,0))}</b></p>
<div class=card style="margin-bottom:1rem"><h3>Ingresar producto</h3><p class=sm>Si el producto no existe, se crea al guardar.</p><div class=fg><input id=cn list=ls placeholder="Producto (nuevo o existente)"><datalist id=ls>${Object.keys(db.ins).map(n=>`<option>${E(n)}`).join('')}</datalist><select id=ck aria-label=Tipo><option value=i>Insumo<option value=s>Salsa</select><input id=cq type=number step=any placeholder=Cantidad><select id=cu aria-label=Unidad>${['und','g','kg','lb'].map(u=>`<option>${u}`).join('')}</select><input id=cv type=number placeholder="Costo total COP"><select id=cs aria-label=Surtidor><option value=tienda>🏪 Compra en tienda${db.sur.map(z=>`<option value=${z.id}>🚚 ${E(z.n)}`).join('')}</select><button class=btn onclick="compra()">Guardar en inventario</button></div></div>
<div class="card scr" style="margin-bottom:1rem"><h3>Insumos</h3><table>${TH}${it('i')}</table></div><div class="card scr" style="margin-bottom:1rem"><h3>Salsas</h3><table>${TH}${it('s')}</table></div>
<div class="card scr"><h3>Historial de compras</h3><input placeholder="🔎 Buscar compra" value="${E(qc)}" oninput="qc=this.value;$('#tc').innerHTML=hc()" style="margin:.6rem 0"><table><tr><th>Fecha y hora<th>Insumo<th>Cantidad<th>Costo<th>Surtidor<th>Registró</tr><tbody id=tc>${hc()}</tbody></table></div>`;
function delIns(k){const n=decodeURIComponent(k),c=db.compras.filter(z=>z.n===n).length;if(!confirm(`¿Eliminar "${n}" del inventario?`+(c?` También se borrarán sus ${c} compra(s) del historial y del reporte.`:'')))return;delete db.ins[n];db.compras=db.compras.filter(z=>z.n!==n);lg(`Eliminó el producto ${n} y sus compras`);save();render()}
function setQ(k,v){const x=IN(k);if(v===''||!(+v>=0))return render();x.s=+v;x.ed=(x.ed||0)+1;if(x.s>x.c)x.c=x.s;lg(`Editó la cantidad de ${decodeURIComponent(k)}: ${v} ${x.u} (edición ${x.ed})`);save();render()}
function compra(){const n=$('#cn').value.trim(),q=+$('#cq').value,v=+$('#cv').value||0,u=$('#cu').value,sur=$('#cs').value;if(!n)return toast('Escribe el producto');if(!(q>0))return toast('Escribe la cantidad');
let x=db.ins[n];const nuevo=!x;if(nuevo)x=db.ins[n]={u,s:0,c:0,k:$('#ck').value,sur,f:null,cost:0,by:'',ed:0};else if((u==='und')!==(x.u==='und'))return toast('Unidad incompatible: este producto se mide en '+x.u);
const b=cv(q,u,x.u);x.s+=b;x.c+=b;x.f=Date.now();x.cost=v;x.sur=sur;x.by=ses.n;db.compras.push({t:Date.now(),n,q,u,v,sur,by:ses.n});lg(`${nuevo?'Creó e ingresó':'Ingresó'} ${q} ${u} de ${n} (${$$(v)}) · ${sn(sur)}`);save();render();toast(nuevo?'Producto creado y guardado':'Ingreso guardado')}
const prodOf=id=>[...new Set([...db.compras.filter(c=>c.sur==id).map(c=>c.n),...Object.keys(db.ins).filter(n=>db.ins[n].sur==id)])].join(', ')||'—',
hs=()=>db.sur.filter(z=>(z.n+' '+(z.emp||'')+' '+(z.mail||'')+' '+(z.tel||'')+' '+prodOf(z.id)).toLowerCase().includes(qs.toLowerCase())).map(z=>{const cs=db.compras.filter(c=>c.sur==z.id),i=db.sur.indexOf(z);return `<tr><td><input value="${E(z.n)}" aria-label=Nombre onchange="db.sur[${i}].n=this.value;save()"><td><input value="${E(z.emp||'')}" placeholder=Empresa aria-label=Empresa onchange="db.sur[${i}].emp=this.value;save()"><td><input type=email value="${E(z.mail||'')}" placeholder=Correo aria-label=Correo onchange="db.sur[${i}].mail=this.value;save()"><td><input value="${E(z.tel||'')}" placeholder="Teléfono / WhatsApp" aria-label=Teléfono onchange="db.sur[${i}].tel=this.value;save()"><td>${E(prodOf(z.id))}<td>${$$(cs.reduce((a,c)=>a+c.v,0))}<td>${cs.length?fd(cs[cs.length-1].t):'—'}<td><button class="btn s" aria-label="Eliminar" onclick="if(confirm('¿Eliminar este surtidor?')){db.sur.splice(${i},1);save();render()}">✕</button></tr>`}).join('')||'<tr><td colspan=8>Sin surtidores</tr>',
ks=()=>`<h2>Surtidores</h2><p class=sm style="margin:.5rem 0 1rem">Guarda quién te vende cada producto. Al ingresar un producto en Inventario eliges su surtidor o “Compra en tienda”.</p><div class=card style="margin-bottom:1rem"><h3>Nuevo surtidor</h3><div class=fg><input id=sn placeholder="Nombre del surtidor"><input id=se placeholder="Empresa que representa"><input id=sm type=email placeholder="Correo"><input id=st placeholder="Teléfono / WhatsApp"><button class=btn onclick="addSur()">Guardar surtidor</button></div></div><div class="card scr"><input placeholder="🔎 Buscar surtidor o producto" value="${E(qs)}" oninput="qs=this.value;$('#ts').innerHTML=hs()" style="margin-bottom:.6rem"><table><tr><th>Surtidor<th>Empresa<th>Correo<th>Teléfono / WhatsApp<th>Productos<th>Total comprado<th>Última compra<th></tr><tbody id=ts>${hs()}</tbody></table></div>`;
function addSur(){const n=$('#sn').value.trim();if(!n)return toast('Escribe el nombre del surtidor');db.sur.push({id:Date.now(),n,emp:$('#se').value.trim(),mail:$('#sm').value.trim(),tel:$('#st').value.trim()});lg('Agregó el surtidor '+n);save();render()}
const kc0=()=>`<h2>Comidas</h2><div class="card scr" style="margin:1rem 0"><table>${db.platos.map(p=>`<tr><td>${p.img?`<img class=pim2 style="width:44px;height:44px;vertical-align:middle" src="${p.img}" alt="">`:p.e} <b>${E(p.n)}</b> <span class=bd>${E(p.c)}</span><div class=pills>${p.v.map(v=>`<span class=pl>${E(v.t)} ${$$(v.p)}</span>`).join('')}</div>${p.c==='Bebidas'?(Object.keys(p.i)[0]?`<div class=pills><span class="pl ig2">📦 ${E(Object.keys(p.i)[0])}</span></div>`:''):`<div class=pills>${ipl(p)}</div><div class=pills>${(p.sa||[]).map(k=>`<span class=pl>🥫 ${E(k)}</span>`).join('')}</div>`}<td><button class="btn s y" onclick="editP(${p.id})">Editar</button> <button class="btn s" onclick="if(confirm('¿Eliminar este plato?')){db.platos=db.platos.filter(x=>x.id!=${p.id});save();render()}">Eliminar</button></tr>`).join('')}</table></div><button class=btn onclick="editP(0)">+ Nuevo plato</button>`;
const kc=()=>`<div class=row style="margin-bottom:1rem"><button class="btn s ${CT==='p'?'y':''}" onclick="CT='p';render()">Platos y bebidas</button><button class="btn s ${CT==='x'?'y':''}" onclick="CT='x';render()">Extras</button></div>`+(CT==='x'?kx():kc0());
const kx=()=>`<h2>Extras</h2><p class=sm style="margin:.5rem 0 1rem">Adicionales con costo (papas, queso, carne…). En cada plato eliges cuáles se ofrecen. Cada extra descuenta su insumo del inventario.</p><datalist id=il2>${Object.keys(db.ins).map(k=>`<option>${E(k)}`).join('')}</datalist>
<div class="card scr"><table><tr><th>Extra<th>Insumo que descuenta<th>Cantidad<th>Unidad<th>Precio<th>Grupo<th></tr>${db.extras.map((x,i)=>`<tr><td><input value="${E(x.n)}" aria-label=Nombre onchange="xe(${i},'n',this.value)"><td><input list=il2 value="${E(x.ins)}" aria-label=Insumo onchange="xe(${i},'ins',this.value)"><td><input type=number step=any value=${x.q} style="width:6rem" aria-label=Cantidad onchange="xe(${i},'q',+this.value)"><td><select aria-label=Unidad onchange="xe(${i},'u',this.value)">${['g','kg','lb','und'].map(u=>`<option${x.u===u?' selected':''}>${u}`).join('')}</select><td><input type=number value=${x.p} style="width:7rem" aria-label=Precio onchange="xe(${i},'p',+this.value)"><td><input value="${E(x.grp||'')}" placeholder="(opcional)" style="width:7rem" aria-label=Grupo onchange="xe(${i},'grp',this.value)"><td><button class="btn s" aria-label="Eliminar" onclick="if(confirm('¿Eliminar este extra?'))delX(${i})">✕</button></tr><tr><td colspan=7><small><b>Se ofrece en:</b></small> <button class="btn s y" onclick="xall(${x.id},1)">Todos</button> <button class="btn s y" onclick="xall(${x.id},0)">Ninguno</button><div class=row style="margin-top:.4rem">${db.platos.map(p=>`<button class="chip px${(p.ex||[]).includes(x.id)?' on':''}" aria-pressed="${(p.ex||[]).includes(x.id)}" onclick="xp(${x.id},${p.id},this)">${p.e} ${E(p.n)}</button>`).join('')}</div></tr>`).join('')||'<tr><td colspan=7>Aún no hay extras</tr>'}</table></div>
<div class=card style="margin-top:1rem"><h3>Nuevo extra</h3><label>¿En qué platos se ofrece?</label><div class=row id=xnp style="margin-bottom:.6rem">${db.platos.map(p=>`<button class="chip px" data-pid=${p.id} onclick="this.classList.toggle('on')">${p.e} ${E(p.n)}</button>`).join('')}</div><div class=fg><input id=xn placeholder="Nombre (ej: Queso extra)"><input id=xi list=il2 placeholder="Insumo que descuenta"><input id=xq type=number step=any placeholder=Cantidad><select id=xu aria-label=Unidad>${['g','kg','lb','und'].map(u=>`<option>${u}`).join('')}</select><input id=xp type=number placeholder="Precio"><input id=xg placeholder="Grupo (opcional)"><button class=btn onclick="addX()">Agregar extra</button></div><p class=sm style="margin-top:.5rem">Grupo: los extras del mismo grupo (por ejemplo “papas”) son excluyentes, se elige solo uno.</p></div>`;
function xe(i,f,v){if(f==='ins'&&!db.ins[v]){render();return toast('Ese insumo no existe en el inventario')}if(f==='n'&&!String(v).trim()){render();return toast('El nombre no puede quedar vacío')}db.extras[i][f]=f==='grp'?String(v).trim():v;save();toast('Guardado')}
function xp(xid,pid,el){const p=db.platos.find(x=>x.id===pid);if(!p)return;p.ex=p.ex||[];const on=!p.ex.includes(xid);p.ex=on?[...p.ex,xid]:p.ex.filter(z=>z!==xid);el.classList.toggle('on',on);el.setAttribute('aria-pressed',on);lg(`${on?'Activó':'Quitó'} el extra "${(db.extras.find(e=>e.id===xid)||{}).n}" en ${p.n}`);save()}
function xall(xid,on){db.platos.forEach(p=>{p.ex=(p.ex||[]).filter(z=>z!==xid);if(on)p.ex.push(xid)});save();render()}
function addX(){const n=$('#xn').value.trim(),ins=$('#xi').value.trim(),q=+$('#xq').value,p=+$('#xp').value;if(!n||!(q>0)||!(p>=0)||$('#xp').value==='')return toast('Completa nombre, cantidad y precio');if(!db.ins[ins])return toast('Ese insumo no existe: ingrésalo primero en Inventario');if(($('#xu').value==='und')!==(db.ins[ins].u==='und'))return toast('Usa el mismo tipo de unidad que el inventario ('+db.ins[ins].u+')');const id=Date.now();db.extras.push({id,n,ins,q,u:$('#xu').value,p,grp:$('#xg').value.trim()});document.querySelectorAll('#xnp .chip.on').forEach(z=>{const pl=db.platos.find(x=>x.id==z.dataset.pid);if(pl)pl.ex=[...(pl.ex||[]),id]});lg('Creó el extra '+n);save();render()}
function delX(i){const id=db.extras[i].id;db.extras.splice(i,1);db.platos.forEach(p=>p.ex=(p.ex||[]).filter(z=>z!==id));save();render()}
function editP(id){PI=(db.platos.find(x=>x.id===id)||{}).img||'';const p=db.platos.find(x=>x.id===id)||{n:'',e:'🍽️',c:'',v:[{t:'',p:'',m:1}],i:{'':''}},m=document.createElement('div');m.className='md';
m.innerHTML=`<div class=card style="max-width:520px;width:92%;max-height:92vh;overflow:auto"><h2>${id?'Editar':'Nuevo'} plato</h2><label>Nombre<input id=pn value="${E(p.n)}"></label><div class=fg><input id=pe value="${E(p.e)}" style="max-width:90px" aria-label=Emoji><input id=pc list=cl value="${E(p.c)}" placeholder="Categoría" oninput="catT(this.value)"><datalist id=cl>${[...new Set(db.platos.map(x=>x.c))].map(c=>`<option>${E(c)}`).join('')}</datalist></div>
<label>Tamaños y precios <small>(consumo: 1 = normal, 0.5 = mitad)</small></label><div id=vl>${p.v.map(VR).join('')}</div><button class="btn s y" style="margin-top:.5rem" onclick="$('#vl').insertAdjacentHTML('beforeend',VR({t:'',p:'',m:1}))">+ Tamaño</button>
<div id=isec ${isB(p.c)?'hidden':''}><label>¿Qué lleva? <small>(cantidad por unidad, en la unidad del insumo)</small></label><datalist id=il>${Object.keys(db.ins).filter(k=>db.ins[k].k!=='s').map(k=>`<option>${E(k)}`).join('')}</datalist><div id=ig>${Object.entries(p.i).map(([k,g])=>IR(k,g)).join('')}</div><button class="btn s y" style="margin-top:.5rem" onclick="$('#ig').insertAdjacentHTML('beforeend',IR('',''))">+ Ingrediente</button></div><div id=bsec ${isB(p.c)?'':'hidden'}><label>Producto del inventario <small>(se descuenta 1 unidad por cada venta)</small></label><select id=bi><option value="">— Ninguno —</option>${Object.keys(db.ins).filter(k=>db.ins[k].k!=='s'&&(db.ins[k].u==='und'||k===Object.keys(p.i||{})[0])).map(k=>`<option${Object.keys(p.i||{})[0]===k?' selected':''}>${E(k)}`).join('')}</select></div>
<label>Extras que se ofrecen en este plato</label><div class=row id=xl>${db.extras.map(x=>`<button class="chip px${(p.ex||[]).includes(x.id)?' on':''}" data-id=${x.id} onclick="this.classList.toggle('on')">${E(x.n)} · +${$$(x.p)}</button>`).join('')||'<span class=sm>Aún no hay extras (créalos en Comidas → Extras)</span>'}</div><label>Foto del plato o bebida <small>(se ve en el menú)</small></label><div class=r style="justify-content:flex-start;gap:1rem"><div id=pvw>${p.img?`<img class=pim2 src="${p.img}" alt="">`:'<span class=sm>Sin foto</span>'}</div><div><input type=file accept="image/*" onchange="upImg(this)"><button class="btn s y" style="margin-top:.4rem" onclick="PI='';$('#pvw').innerHTML='<span class=sm>Sin foto</span>'">Quitar foto</button></div></div><div id=ssec ${isB(p.c)?'hidden':''}><label>Salsas que lleva <small>(vienen encendidas al pedir)</small></label><div class=row id=sl>${Object.keys(db.ins).filter(k=>db.ins[k].k==='s').map(k=>`<button class="chip sa${(p.sa||[]).includes(k)?' on':''}" onclick="this.classList.toggle('on')">${E(k)}</button>`).join('')}</div></div><div class=row style="margin-top:1rem"><button class=btn onclick="saveP(${id})">Guardar</button><button class="btn y" onclick="this.closest('.md').remove()">Cancelar</button></div></div>`;document.body.append(m)}
function saveP(id){const n=$('#pn').value.trim(),c=isB($('#pc').value)?'Bebidas':$('#pc').value.trim(),v=[...document.querySelectorAll('#vl .vrow')].map(r=>{const[a,b,k]=r.querySelectorAll('input');return{t:a.value.trim(),p:+b.value,m:+k.value||1}}).filter(x=>x.t&&x.p>0),i={};
if(c==='Bebidas'){const z=$('#bi').value;if(z)i[z]={q:1,u:'und'}}else document.querySelectorAll('#ig .irow').forEach(r=>{const[a,b]=r.querySelectorAll('input'),k=a.value.trim();if(k&&+b.value>0)i[k]={q:+b.value,u:r.querySelector('select').value}});
if(!n||!c||!v.length||(c!=='Bebidas'&&!Object.keys(i).length))return toast(c==='Bebidas'?'Completa nombre, categoría y al menos un tamaño con precio':'Completa nombre, categoría, al menos un tamaño con precio y un ingrediente');
const x=Object.keys(i).find(k=>!db.ins[k]);if(x)return toast('El insumo "'+x+'" no existe: ingrésalo primero en Inventario');
const y=Object.keys(i).find(k=>(i[k].u==='und')!==(db.ins[k].u==='und'));if(y)return toast('"'+y+'" se mide en '+db.ins[y].u+': usa el mismo tipo de unidad');
const d={id:id||Date.now(),n,c,e:$('#pe').value||'🍽️',v,i,img:PI,ex:[...document.querySelectorAll('#xl .px.on')].map(z=>+z.dataset.id),sa:c==='Bebidas'?[]:[...document.querySelectorAll('#sl .sa.on')].map(z=>z.textContent)};id?db.platos[db.platos.findIndex(z=>z.id===id)]=d:db.platos.push(d);lg((id?'Editó':'Creó')+' plato '+n);save();$('.md').remove();render()}
const vlist=()=>db.pedidos.slice().reverse().filter(o=>o.est!=='cancelado').filter(o=>(`#${o.id} ${o.d} ${o.nom} ${o.mp} ${o.o} ${o.m||''} ${fd(o.t)} ${o.it.map(c=>c.n).join(' ')}`).toLowerCase().includes(qv.toLowerCase())),
hv=()=>vlist().map(o=>`<tr><td>#${o.id}<td>${fd(o.t)}<td>${o.o==='web'?'Compra web':'Mesera '+E(o.m)}<td>${E(o.d)}<td>${E(o.mp||'—')}<td>${$$(o.tot)}<td>${o.pg==='pagado'?'✅':'⏳'}</tr>`).join('')||'<tr><td colspan=7>Sin ventas</tr>';
const kr=()=>{const day=i=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);return+d},ok=db.pedidos.filter(o=>o.est!=='cancelado'),w0=day(6),sum=(l,f)=>l.filter(f).reduce((a,o)=>a+(o.tot??o.v),0),
sem=ok.filter(o=>o.t>=w0),ing=sum(ok,o=>o.t>=w0),cob=sum(ok,o=>o.t>=w0&&o.pg==='pagado'),inv=sum(db.compras,c=>c.t>=w0),gan=ing-inv,mg=ing?gan/ing*100:0,
ds=[6,5,4,3,2,1,0].map(i=>({l:DN[new Date(day(i)).getDay()].slice(0,3),v:sum(ok,o=>o.t>=day(i)&&o.t<day(i)+864e5)})),mx=Math.max(1,...ds.map(d=>d.v)),cn={};
sem.forEach(o=>o.it.forEach(c=>cn[c.n]=(cn[c.n]||0)+1));const star=(bv,t)=>{const r=Object.entries(cn).filter(([nm])=>(db.platos.find(p=>p.n===nm)?.c==='Bebidas')===bv).sort((a,b)=>b[1]-a[1])[0],p=r&&db.platos.find(x=>x.n===r[0]);return `<div class="card star"><span class=bd>⭐ ${t}</span>${!r?`<div style="font-size:5rem;margin:1rem 0">${bv?'🥤':'🍽️'}</div><h3>Aún sin ventas</h3>`:`${p?.img?`<img class=pim src="${p.img}" alt="${E(r[0])}" style="margin-top:.8rem">`:`<div style="font-size:6.5rem;margin:.5rem 0">${p?.e||'🍽️'}</div>`}<h3>${E(r[0])}</h3><p class=sm>${r[1]} vendido(s) esta semana</p>`}</div>`},mxb=Math.max(1,ing,inv),
K2=[['Invertido',$$(inv)],['Vendido',$$(ing)],['Ganancia',`<span class=${gan>=0?'ok':'ko'}>${$$(gan)}</span>`],['Margen',mg.toFixed(0)+'%'],['Pedidos',sem.length],['Ticket promedio',$$(sem.length?ing/sem.length:0)],['Cobrado',$$(cob)],['Por cobrar',$$(ing-cob)],['Compras web',sem.filter(o=>o.o==='web').length]];
return `<h2>Reporte de la semana</h2><div class=stars>${star(false,'Plato estrella')}${star(true,'Bebida estrella')}</div><div class=grid style="margin:1rem 0;grid-template-columns:repeat(auto-fill,minmax(150px,1fr))">${K2.map(([l,v])=>`<div class="card kpi"><p class=sm>${l}</p><h3 class=pr>${v}</h3></div>`).join('')}</div>
<div class=card style="margin-bottom:1rem"><h3>Inversión vs. ganancia</h3><p class=sm style="margin-top:.8rem">Invertido ${$$(inv)}</p><div class=bar style="height:22px"><i style="width:${inv/mxb*100}%;background:#c4161c"></i></div><p class=sm style="margin-top:.6rem">Vendido ${$$(ing)}</p><div class=bar style="height:22px"><i style="width:${ing/mxb*100}%;background:#168a2e"></i></div><p style="margin-top:.8rem"><b>Ganancia: <span class=${gan>=0?'ok':'ko'}>${$$(gan)}</span></b> (${mg.toFixed(0)}% de lo vendido)</p></div>
<div class=card style="margin-bottom:1rem"><h3>Ventas por día</h3><div style="display:flex;gap:.6rem;align-items:flex-end;height:160px;margin-top:1rem">${ds.map(d=>`<div style="flex:1;text-align:center"><small>${d.v?$$(d.v):''}</small><div style="height:${d.v/mx*110}px;min-height:4px;background:var(--a);border:2px solid var(--ln);border-radius:8px 8px 0 0"></div><small>${d.l}</small></div>`).join('')}</div></div>
<div class="card scr" style="margin-bottom:1rem"><div class=r><h3>Historial de ventas</h3><button class="btn s" onclick="pdfV()">⬇️ Descargar PDF</button></div><input placeholder="🔎 Buscar venta (plato, mesera, método, fecha…)" value="${E(qv)}" oninput="qv=this.value;$('#tv').innerHTML=hv()" style="margin:.6rem 0"><table><tr><th>#<th>Fecha y hora<th>Origen<th>Destino<th>Pago<th>Total<th></tr><tbody id=tv>${hv()}</tbody></table></div>
<div class="card scr"><h3>Historial de compra de insumos</h3><input placeholder="🔎 Buscar compra" value="${E(qc)}" oninput="qc=this.value;$('#tc').innerHTML=hc()" style="margin:.6rem 0"><table><tr><th>Fecha y hora<th>Insumo<th>Cantidad<th>Costo<th>Surtidor<th>Registró</tr><tbody id=tc>${hc()}</tbody></table></div>`};
const ku=()=>`<h2>Ingresos y acciones del personal</h2><div class="card scr" style="margin-top:1rem"><table><tr><th>Fecha y hora<th>Persona<th>Acción</tr>${db.logs.slice(-200).reverse().map(l=>`<tr><td>${fd(l.t)}<td>${E(l.n)}<td>${E(l.a)}</tr>`).join('')||'<tr><td colspan=3>Aún no hay registros</tr>'}</table></div>`;
const ka=()=>{const c=db.cfg,f=(k,l)=>`<label>${l}<input value="${E(c[k])}" onchange="db.cfg.${k}=this.value;save()"></label>`;return `<h2>Ajustes</h2>
<div class=card style="margin:1rem 0"><h3>Nombre y mensajes</h3>${f('n','Nombre del negocio')}${f('w1','Título principal')}${f('w2','Subtítulo')}${f('w3','Mensaje destacado')}${f('w4','Sello (Todo a tu gusto)')}</div>
<div class=card style="margin-bottom:1rem"><h3>Contacto</h3>${f('tel','Teléfono y WhatsApp')}</div>
<div class=card style="margin-bottom:1rem"><h3>Logo del local</h3><div class=r style="justify-content:flex-start;gap:1rem;margin-top:.6rem"><img class=lg2 src="${logoSrc()}" alt="Logo actual"><div><input type=file accept="image/*" onchange="upLogo(this)"><button class="btn s y" style="margin-top:.5rem" onclick="db.cfg.logo='';save();render()">Usar el logo original</button></div></div></div>
<div class=card style="margin-bottom:1rem"><h3>Fondo de pantalla</h3><p class=sm>Se muestra detrás de toda la página. Mejor una imagen horizontal.</p><input type=file accept="image/*" onchange="upBg(this)" style="margin:.6rem 0"><button class="btn s y" onclick="db.cfg.bg='';save();render()">Quitar fondo</button></div>
<div class=card style="margin-bottom:1rem"><h3>Horarios</h3><p class=sm>Hora de abrir y cerrar (0-24). Deja vacío para cerrado.</p>${[1,2,3,4,5,6,0].map(d=>`<div class=fg><b style="width:6rem">${DN[d]}</b><input type=number step=.5 value="${c.h[d]?.[0]??''}" onchange="hh(${d},0,this.value)" aria-label="Abre"><input type=number step=.5 value="${c.h[d]?.[1]??''}" onchange="hh(${d},1,this.value)" aria-label="Cierra"></div>`).join('')}</div>
<div class=card style="margin-bottom:1rem"><h3>Métodos de pago</h3>${Object.entries(c.pay).map(([k,x])=>`<div class=fg><label style="margin:0;min-width:140px"><input type=checkbox style="width:auto" ${x.on?'checked':''} onchange="db.cfg.pay['${k}'].on=this.checked?1:0;save()"> ${E(x.n)}</label>${k==='ef'?'':`<input value="${E(x.num)}" placeholder="Número de cuenta/celular" onchange="db.cfg.pay['${k}'].num=this.value;save()"><button class="btn s" aria-label="Quitar método" onclick="delPay('${k}')">✕</button>`}</div>`).join('')}<div class=fg style="border-top:2px dashed var(--ln);padding-top:.6rem"><input id=npn placeholder="Nuevo método (ej: Bancolombia QR)"><input id=npu placeholder="Número o cuenta (opcional)"><button class=btn onclick="addPay()">+ Agregar método</button></div></div>
<div class=card style="margin-bottom:1rem"><h3>Mesas</h3><label>Cantidad de mesas<input type=number min=1 value=${c.mesas} onchange="db.cfg.mesas=Math.max(1,+this.value||1);save()"></label></div>
<div class=card style="margin-bottom:1rem"><h3>Administrador de cocina</h3><div class=fg><input id=au value="${E(db.adm.u)}" placeholder=Usuario><input id=ap value="${E(db.adm.p)}" placeholder=Contraseña><button class=btn onclick="adm()">Guardar acceso</button></div></div>
<div class=card><h3>Meseras</h3><table>${db.meseras.map((m,i)=>`<tr><td>${E(m.n)} <small>(${E(m.u)})</small><td><button class="btn s" onclick="db.meseras.splice(${i},1);save();render()">Quitar</button></tr>`).join('')}</table><div class=fg><input id=mn placeholder=Nombre><input id=mu placeholder=Usuario><input id=mp placeholder=Contraseña><button class=btn onclick="addMes()">Agregar mesera</button></div></div><div class=svb><button class=btn onclick="guardar()">💾 Guardar cambios</button></div>`};
function addPay(){const n=$('#npn').value.trim();if(!n)return toast('Escribe el nombre del método');db.cfg.pay['p'+Date.now()]={n,on:1,num:$('#npu').value.trim()};lg('Agregó método de pago '+n);save();render()}
const delPay=k=>{if(confirm('¿Quitar este método de pago?')){delete db.cfg.pay[k];save();render()}};
function guardar(){document.activeElement?.blur();save();toast('✅ Cambios guardados')}
const hh=(d,i,v)=>{const x=db.cfg.h[d]||[18,22];x[i]=+v;db.cfg.h[d]=v===''?null:x;save()};
function adm(){const u=$('#au').value.trim().toLowerCase(),p=$('#ap').value;if(!u||!p||u===db.dev.u)return toast('Usuario o contraseña no válidos');db.adm={u,p};lg('Cambió el acceso de administrador');save();toast('Acceso actualizado')}
function addMes(){const n=$('#mn').value.trim(),u=$('#mu').value.trim().toLowerCase(),p=$('#mp').value;if(!n||!u||!p||u===db.dev.u||u===db.adm.u||db.meseras.some(m=>m.u===u))return toast('Datos incompletos o usuario repetido');db.meseras.push({n,u,p});save();render()}

/* ---------- MESERA ---------- */
function mesera(){const lis=db.pedidos.filter(o=>o.est==='listo'&&(o.m===ses.u||o.o==='web'));
app(shell(`<div class=tabs><button class="btn s ${mtab==='n'?'y':''}" onclick="mtab='n';render()">Nuevo pedido</button><button class="btn s ${mtab==='h'?'y':''}" onclick="mtab='h';render()">Historial${lis.length?' 🔔'+lis.length:''}</button></div>`+(mtab==='n'?`<div class=cols><div>${menu()}</div>${ticket()}</div>`:hist(lis)),1));tick()}
const card=o=>`<div class=card><div class=r><h3>#${o.id}</h3><span class=bd>${o.o==='web'?'🌐 Compra web':o.est}</span></div><p><b>${E(o.d)}</b>${o.nom?' · '+E(o.nom):''} · ${$$(o.tot)}</p><p class=sm>${o.it.map(c=>E(c.n)+' ('+E(c.v)+')').join(', ')}</p><p class=sm>${o.tel?'📞 '+E(o.tel)+' · ':''}${o.o==='web'?'Estado: '+o.est+(o.mp?' · pagará: '+E(o.mp):''):''}</p><div class=row style="margin-top:.7rem">${o.pg==='pagado'?`<span class=bd>Pagado ✓ ${E(o.mp)}</span>`:o.est==='listo'||o.est==='entregado'?`<button class="btn s" onclick="cobrar(${o.id})">Confirmar pago</button>`:o.o==='web'?'<span class=bd>En cocina…</span>':'<span class=bd>En deuda</span>'}${o.est==='nuevo'&&o.o!=='web'?`<button class="btn s y" onclick="editar(${o.id})">Editar</button><button class="btn s" onclick="est(${o.id},'cancelado')">Cancelar</button>`:''}${o.est==='listo'?`<button class="btn s y" onclick="est(${o.id},'entregado')">Ya lo entregué</button>`:''}${o.est!=='cancelado'?`<button class="btn s y" onclick="recibo(${o.id})">Tirilla</button>`:''}</div></div>`;
const hist=lis=>{const mine=db.pedidos.filter(o=>o.m===ses.u).reverse(),web=db.pedidos.filter(o=>o.o==='web'&&o.est!=='cancelado').reverse();return `${lis.map(o=>`<div class=card style="background:var(--a2);color:#1c120a;margin-bottom:1rem"><h3>✅ #${o.id} listo para ${E(o.d)}${o.o==='web'?' · COMPRA WEB':''}</h3></div>`).join('')}<h2 style="margin:1rem 0">Compras web</h2><div class=grid>${web.map(card).join('')||'<div class=card>No hay compras web.</div>'}</div><h2 style="margin:1.5rem 0 1rem">Mis pedidos</h2><div class=grid>${mine.map(card).join('')||'<div class=card>Aún no has enviado pedidos.</div>'}</div>`};
const est=(id,e)=>{db.pedidos.find(x=>x.id===id).est=e;lg(`Pedido #${id}: ${e}`);save();render()};
function cobrar(id){const m=document.createElement('div');m.className='md';m.innerHTML=`<div class=card style="max-width:360px;width:92%"><h2>Pedido #${id}</h2><p class=sm style="margin:.5rem 0">Total ${$$(db.pedidos.find(x=>x.id===id).tot)} · ¿Cómo pagó?</p><div class=row>${Object.entries(db.cfg.pay).filter(([,x])=>x.on).map(([k,x])=>`<button class="btn y" onclick="pagar(${id},'${k}')">${E(x.n)}</button>`).join('')}</div><button class="btn s" style="margin-top:1rem" onclick="this.closest('.md').remove()">Cancelar</button></div>`;document.body.append(m)}
function pagar(id,k){const o=db.pedidos.find(x=>x.id===id),mp=db.cfg.pay[k].n;o.pg='pagado';o.mp=mp;o.cf=ses.u;o.tp=Date.now();lg(`Confirmó pago #${id} (${mp}) ${$$(o.tot)}`);save();$('.md').remove();render()}
function editar(id){const o=db.pedidos.find(x=>x.id===id);edit=id;cart=o.it.map(c=>({...c}));fm={d:o.d,nom:o.nom,dir:o.dir,tel:o.tel||'',mp:''};mtab='n';render()}

/* ---------- ROUTER ---------- */
function render(){const r=location.hash.slice(1);setT();bgInit();ico();wall();
if(r==='cocina'&&ses?.r==='a'&&activo())cocina();else if(r==='mesera'&&ses?.r==='m'&&activo())mesera();else if(r==='dev'&&ses?.r==='x')dev();else if(['personal','cocina','mesera','dev'].includes(r))login();
else cliente();if(!SPL){SPL=1;splash(db.cfg.w1)}tick()}
addEventListener('storage',e=>{if(e.key!==K||!e.newValue)return;const o=db;db=JSON.parse(e.newValue);detect(o);if(!$('#lu')&&!$('.md'))render()});
onhashchange=render;render();
